import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const root = path.dirname(new URL(import.meta.url).pathname);
const port = Number(process.env.PORT || 3000);
const profiles = new Map();
const profileFile = path.join(root, '.ashen-profiles.json');
try { for (const [id, p] of Object.entries(JSON.parse(fs.readFileSync(profileFile, 'utf8')))) profiles.set(id, p); } catch {}

const clients = new Map();
const MAX_PLAYERS = 15;
const boss = { hp: 50000, max: 50000, phase: 0, attack: null };

function saveProfiles() {
  fs.writeFile(profileFile, JSON.stringify(Object.fromEntries(profiles), null, 2), () => {});
}
function safeProfile(id) {
  const p = profiles.get(id) || { rank: 0, wins: 0, bosses: 0, damage: 0, deaths: 0, matches: 0 };
  profiles.set(id, p); return p;
}
function frame(op, data) { return Buffer.from(JSON.stringify({ op, ...data })); }
function broadcast(op, data) {
  const wire = frame(op, data);
  for (const c of clients.values()) if (c.ws.readyState === 1) c.ws.send(wire);
}
function snapshot() {
  return { type: 'snapshot', boss, players: [...clients.values()].map(c => ({ id: c.id, name: c.name, x: c.x, y: c.y, hp: c.hp, dir: c.dir, profile: safeProfile(c.profileId) })) };
}

const server = http.createServer((req, res) => {
  if (req.url === '/health') { res.writeHead(200, {'content-type':'application/json'}); return res.end(JSON.stringify({ ok:true, players:clients.size, max:MAX_PLAYERS, bossHp:boss.hp })); }
  let file = req.url === '/' ? '/index.html' : req.url.split('?')[0];
  file = path.normalize(file).replace(/^([/\\])+/, '');
  const full = path.join(root, file);
  if (!full.startsWith(root) || !fs.existsSync(full) || fs.statSync(full).isDirectory()) { res.writeHead(404); return res.end('Not found'); }
  const ext = path.extname(full);
  const types = { '.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.png':'image/png' };
  res.writeHead(200, {'content-type':types[ext] || 'application/octet-stream'});
  fs.createReadStream(full).pipe(res);
});

const MAGIC = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
server.on('upgrade', (req, socket) => {
  if (clients.size >= MAX_PLAYERS) { socket.destroy(); return; }
  const key = req.headers['sec-websocket-key'];
  if (!key) return socket.destroy();
  socket.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Acetp: ' + crypto.createHash('sha1').update(key + MAGIC).digest('base64') + '\r\n\r\n');

  const id = crypto.randomUUID();
  socket.buffer = Buffer.alloc(0);
  socket.readyState = 1;
  socket.receive = (data) => {
    socket.buffer = Buffer.concat([socket.buffer, data]);
    while (socket.buffer.length >= 2) {
      const b1 = socket.buffer[0], b2 = socket.buffer[1];
      const masked = !!(b2 & 128); let len = b2 & 127, pos = 2;
      if (len === 126) { if (socket.buffer.length < 4) return; len = socket.buffer.readUInt16BE(2); pos = 4; }
      else if (len === 127) { if (socket.buffer.length < 10) return; len = Number(socket.buffer.readBigUInt64BE(2)); pos = 10; }
      let mask; if (masked) { if (socket.buffer.length < pos + 4) return; mask = socket.buffer.subarray(pos, pos + 4); pos += 4; }
      if (socket.buffer.length < pos + len) return;
      let payload = socket.buffer.subarray(pos, pos + len); if (masked) payload = Buffer.from(payload.map((v,i) => v ^ mask[i%4]));
      socket.buffer = socket.buffer.subarray(pos + len);
      const op = b1 & 15;
      if (op === 8) return socket.end();
      if (op === 9) { socket.write(Buffer.from([0x8a, payload.length, ...payload])); continue; }
      if (op === 1) handleMessage(socket, id, payload.toString());
      if (op === 2) handleMessage(socket, id, payload);
    }
  };
  socket.on('data', socket.receive);
  socket.send = (buf) => { if (socket.readyState !== 1) return; const n=buf.length; let h=n<126?Buffer.from([0x81,n]):n<65536?Buffer.concat([Buffer.from([0x81,126]),Buffer.alloc(2).fill(0)]):null; if(n<126)socket.write(Buffer.concat([h,buf])); else if(n<65536){h.writeUInt16BE(n,2);socket.write(Buffer.concat([h,buf]));} else {const hdr=Buffer.alloc(10);hdr[0]=0x81;hdr[1]=127;hdr.writeBigUInt64BE(BigInt(n),2);socket.write(Buffer.concat([hdr,buf]));} };
  socket.on('close', () => { clients.delete(id); broadcast('leave',{id}); saveProfiles(); });
  socket.readyState = 1;
});

function handleMessage(socket, id, raw) {
  let msg; try { msg = typeof raw === 'string' ? JSON.parse(raw) : JSON.parse(raw.toString()); } catch { return; }
  if (msg.op === 'join') {
    const profileId = String(msg.profileId || id).slice(0,64); const name = String(msg.name || 'Ashen Warrior').replace(/[^\p{L}\p{N} _-]/gu,'').slice(0,18) || 'Ashen Warrior';
    if (clients.has(id)) return;
    clients.set(id,{ id, ws:socket, name, profileId, x:0, y:145, hp:100, dir:-Math.PI/2 });
    socket.send(frame('joined',{id,boss,players:[...clients.values()].map(c=>({id:c.id,name:c.name,x:c.x,y:c.y,hp:c.hp,dir:c.dir,profile:safeProfile(c.profileId)}))}));
    broadcast('join',{id,name,profile:safeProfile(profileId)}); return;
  }
  const c = clients.get(id); if (!c) return;
  if (msg.op === 'state') { c.x=Number(msg.x)||0;c.y=Number(msg.y)||0;c.dir=Number(msg.dir)||0;c.hp=Math.max(0,Math.min(100,Number(msg.hp)||c.hp)); broadcast('player',{id, x:c.x,y:c.y,hp:c.hp,dir:c.dir }); }
  if (msg.op === 'hit') {
    const dmg = 20; if (boss.hp > 0) { boss.hp = Math.max(0,boss.hp-dmg); boss.phase=boss.hp<=12500?3:boss.hp<=25000?2:boss.hp<=37500?1:0; const p=safeProfile(c.profileId);p.damage=(p.damage||0)+dmg;saveProfiles(); broadcast('boss',{hp:boss.hp,phase:boss.phase,hitter:id}); }
  }
  if (msg.op === 'profile') { const p=safeProfile(c.profileId); p.matches=(p.matches||0)+1; if(msg.victory)p.wins=(p.wins||0)+1;if(msg.death)p.deaths=(p.deaths||0)+1;saveProfiles(); }
}

setInterval(() => broadcast('snapshot',snapshot()), 1000);
server.listen(port, '0.0.0.0', () => console.log(`Ashen Arena server listening on http://0.0.0.0:${port}`));

