tePlayers.size+1)}};socket.onerror=()=>{};socket.onclose=()=>{if(network!==socket)return;network=null;networkId=null;const wasOnline=onlineMatch;networkJoined=false;remotePlayers.clear();syncPlayerCount(1);updateConnectionStatus();if(wasOnline&&state==='playing'){onlineMatch=false;showToast('CO-OP CONNECTION LOST · CONTINUING SOLO')}}}catch(e){network=null;networkJoined=false;updateConnectionStatus()}}
