import assert from 'node:assert/strict';
const url = 'ws://127.0.0.1:3012/arena';
function connect(profileId, name) {
  const ws = new WebSocket(url);
  const messages = [];
  ws.addEventListener('message', e => messages.push(JSON.parse(e.data)));
  return new Promise((resolve, reject) => {
    ws.addEventListener('open', () => ws.send(JSON.stringify({op:'join', profileId, name})));
    ws.addEventListener('error', reject);
    const timer = setTimeout(() => reject(new Error('join timed out')), 3000);
    const poll = setInterval(() => {
      const joined = messages.find(m => m.op === 'joined');
      if (joined) { clearTimeout(timer); clearInterval(poll); resolve({ws, messages, joined}); }
    }, 10);
  });
}
const a = await connect('test_a', 'Ash One');
const b = await connect('test_b', 'Ash Two');
assert.equal(a.joined.boss.hp, 50000);
assert.equal(a.joined.profile.matches, 1);
a.ws.send(JSON.stringify({op:'state', x:0, y:145, dir:-Math.PI/2, hp:0}));
await new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error('death profile update timed out')), 1500);
  const poll = setInterval(() => {
    const p = a.messages.find(m => m.op === 'profile' && m.profile.deaths === 1);
    if (p) { clearTimeout(timer); clearInterval(poll); resolve(); }
  }, 10);
});
assert.ok(b.messages.some(m => m.op === 'player' && m.name === 'Ash One' && m.hp === 0));
const health = await fetch('http://127.0.0.1:3012/health').then(r => r.json());
assert.equal(health.players, 2);
a.ws.close(); b.ws.close();
console.log('PASS: HTTP health, two-player join/snapshot, state broadcast, server-counted death.');
