    const profile = safeProfile(profileId);
    profile.matches = (profile.matches || 0) + 1;
    saveProfiles();
    send(socket, 'joined', { id, boss: { hp: boss.hp, max: boss.max, phase: boss.phase }, players: snapshot().players, profile });
