const targets = await (await fetch('http://127.0.0.1:9224/json')).json();
const target = targets.find(t => t.type === 'page') ?? await (await fetch('http://127.0.0.1:9224/json/new?about:blank', { method: 'PUT' })).json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
let nextId = 0;
const pending = new Map();
const events = [];
ws.onmessage = event => {
  const message = JSON.parse(event.data);
  if (message.id) {
    const request = pending.get(message.id);
    if (request) { pending.delete(message.id); message.error ? request.reject(message.error) : request.resolve(message.result); }
  } else events.push(message);
};
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
function cdp(method, params = {}) {
  const id = ++nextId;
  return new Promise((resolve, reject) => { pending.set(id, { resolve, reject }); ws.send(JSON.stringify({ id, method, params })); });
}
const evalJs = async expression => {
  const result = await cdp('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
  return result.result?.value;
};
await cdp('Page.enable');
await cdp('Runtime.enable');
await cdp('Network.enable');
await cdp('Page.navigate', { url: 'http://127.0.0.1:3013/' });
await new Promise(resolve => setTimeout(resolve, 1200));
const menu = await evalJs(`({title:document.querySelector('.title')?.innerText, status:document.querySelector('#connectionStatus')?.innerText, input:!!document.querySelector('#nameInput'), errors:document.querySelector('#panel')?.innerText})`);
await evalJs(`document.querySelector('#nameInput').value='Browser Test';document.querySelector('#nameInput').dispatchEvent(new Event('input',{bubbles:true}));window.playAgain()`);
await new Promise(resolve => setTimeout(resolve, 500));
const game = await evalJs(`({player:document.querySelector('.player-name')?.innerText,count:document.querySelector('#count')?.innerText,boss:document.querySelector('#bossHp')?.innerText,hp:document.querySelector('#playerHp')?.innerText,canvas:[document.querySelector('canvas').width,document.querySelector('canvas').height]})`);
await cdp('Input.dispatchKeyEvent', { type: 'keyDown', key: ' ', code: 'Space', windowsVirtualKeyCode: 32 });
await new Promise(resolve => setTimeout(resolve, 350));
await cdp('Input.dispatchKeyEvent', { type: 'keyUp', key: ' ', code: 'Space', windowsVirtualKeyCode: 32 });
await new Promise(resolve => setTimeout(resolve, 200));
const hit = await evalJs(`({boss:document.querySelector('#bossHp')?.innerText,phase:document.querySelector('#phase')?.innerText,connection:document.querySelector('#connectionStatus')?.innerText,errors:document.querySelector('#panel')?.innerText})`);
const screenshot = await cdp('Page.captureScreenshot', { format: 'png' });
await import('node:fs/promises').then(fs => fs.writeFile('/tmp/opencode/ashen-browser.png', Buffer.from(screenshot.data, 'base64')));
console.log(JSON.stringify({ menu, game, hit, runtimeErrors: events.filter(e => ['Runtime.exceptionThrown', 'Log.entryAdded'].includes(e.method)).map(e => e.params).slice(0, 10), network: events.filter(e => e.method.startsWith('Network.webSocket')).map(e => e.method) }, null, 2));
ws.close();

